import * as _ from './stuff.mjs';
import * as DOM from './DOM.mjs';
import controllers from './controllers.mjs';

class HBase extends HTMLElement {
	get options() { return this.behavior || {}; }
}

class Panel extends HBase {
	connectedCallback() {
		this.#connectController();
	}
	#connectController() {
		let name = this.getAttribute('name');
		if (!name) return;
		let value = this.getAttribute('value');
		this.hidden = true;
		if (!controllers.has(name)) controllers.create(name);
		controllers.listen(name, (values) => { this.hidden = !_.includes(values, value); });
	}
	static isPanel(element) { return element instanceof Panel; }
}

/**
 * Base class for directional layouts (VLayout, HLayout).
 * Owns all child sizing via flex properties set in JS.
 */
class BaseLayout extends Panel {
	connectedCallback() {
		super.connectedCallback();
		// Defer sizing so all children are upgraded first
		queueMicrotask(() => this.#initChildren());
	}

	/**
	 * Set flex properties on all child panels/layouts/splitters.
	 * - Panels with explicit size → flex: 0 0 <size>
	 * - Panels without size → flex: 1 1 0 (fill remaining)
	 * - Splitters → flex: 0 0 4px (already in CSS)
	 * - Layouts → flex: 1 1 0 (fill remaining)
	 * - Other elements → hidden
	 */
	#initChildren() {
		let isVertical = this instanceof VLayout;
		for (let node of Array.from(this.childNodes)) {
			if (node.nodeType === 3) {
				if (/^\s*$/.test(node.nodeValue)) { this.removeChild(node); continue; }
				let wbr = this.ownerDocument.createElement('wbr');
				wbr.hidden = true;
				this.replaceChild(wbr, node);
				wbr.appendChild(node);
				continue;
			}
			if (node.nodeType !== 1) continue;
			if (Splitter.isSplitter(node)) continue; // sized by CSS
			if (!(Panel.isPanel(node) || VLayout.isLayout(node))) {
				node.hidden = true;
				continue;
			}
			// Determine sizing
			let size = isVertical ? node.getAttribute('height') : node.getAttribute('width');
			if (size) {
				node.style.flex = `0 0 ${size}`;
			} else {
				node.style.flex = '1 1 0';
				node.style.minWidth = '0';
				node.style.minHeight = '0';
				node.style.overflow = 'hidden';
			}
		}
	}

	static isLayout(element) { return element instanceof VLayout || element instanceof HLayout; }
}

class VLayout extends BaseLayout {
}

class HLayout extends BaseLayout {
}

class Deck extends Panel {
	connectedCallback() {
		// Skip Panel's #connectController — Deck uses name differently (to drive children, not self)
		queueMicrotask(() => {
			this.#normalizeChildren();
			this.#connectDeckController();
		});
	}
	get owns() {
		return _.filter(Array.from(this.children), (el) => {
			return Panel.isPanel(el) || VLayout.isLayout(el);
		});
	}
	set activedescendant(item) {
		let panels = this.owns;
		if (item && !_.includes(panels, item)) throw Error('set activedescendant failed: item is not child of deck');
		_.forEach(panels, (child) => { child.hidden = (child !== item); });
	}
	#normalizeChildren() {
		for (let node of Array.from(this.childNodes)) {
			if (node.nodeType === 1) {
				if (Panel.isPanel(node) || VLayout.isLayout(node)) continue;
				node.hidden = true;
			} else if (node.nodeType === 3) {
				if (/^\s*$/.test(node.nodeValue)) this.removeChild(node);
			}
		}
	}
	#connectDeckController() {
		let name = this.getAttribute('name');
		if (!name) { this.activedescendant = this.owns[0]; return; }
		if (!controllers.has(name)) controllers.create(name);
		controllers.listen(name, (values) => {
			let activePanel = _.find(this.owns, (child) => {
				let value = child.getAttribute('value');
				return _.includes(values, value);
			});
			this.activedescendant = activePanel || this.owns[0];
		});
	}
}


class Splitter extends HBase {
	connectedCallback() {
		this.addEventListener('pointerdown', (e) => this.#startResize(e));
	}

	/**
	 * Begin a resize operation on pointerdown.
	 * Adjusts flex-basis of the previous and next sibling panels.
	 * @param {PointerEvent} startEvent
	 */
	#startResize(startEvent) {
		startEvent.preventDefault();
		this.setPointerCapture(startEvent.pointerId);

		let prev = this.previousElementSibling;
		let next = this.nextElementSibling;
		if (!prev || !next) return;

		let parent = this.parentElement;
		let isVertical = parent instanceof VLayout;
		let startPos = isVertical ? startEvent.clientY : startEvent.clientX;
		let prevSize = isVertical ? prev.offsetHeight : prev.offsetWidth;
		let nextSize = isVertical ? next.offsetHeight : next.offsetWidth;

		// Read constraints
		let prevMin = parseFloat(prev.getAttribute('min-width') || prev.getAttribute('min-height') || '0');
		let prevMax = parseFloat(prev.getAttribute('max-width') || prev.getAttribute('max-height') || 'Infinity');
		let nextMin = parseFloat(next.getAttribute('min-width') || next.getAttribute('min-height') || '0');
		let nextMax = parseFloat(next.getAttribute('max-width') || next.getAttribute('max-height') || 'Infinity');

		let onMove = (e) => {
			let delta = (isVertical ? e.clientY : e.clientX) - startPos;
			// Clamp delta to respect min/max constraints
			let newPrev = prevSize + delta;
			let newNext = nextSize - delta;
			if (newPrev < prevMin) delta = prevMin - prevSize;
			else if (newPrev > prevMax) delta = prevMax - prevSize;
			if (newNext < nextMin) delta = nextSize - nextMin;
			else if (newNext > nextMax) delta = -(nextMax - nextSize);

			prev.style.flexBasis = (prevSize + delta) + 'px';
			next.style.flexBasis = (nextSize - delta) + 'px';
		};

		let onUp = () => {
			this.removeEventListener('pointermove', onMove);
			this.removeEventListener('pointerup', onUp);
			this.releasePointerCapture(startEvent.pointerId);
		};

		this.addEventListener('pointermove', onMove);
		this.addEventListener('pointerup', onUp);
	}

	static isSplitter(element) { return element instanceof Splitter; }
}

/**
 * Register all layout custom elements using the detected namespace prefix.
 * @param {CustomNamespace} ns - The namespace for resolving tag names.
 */
function registerLayoutElements(ns) {
	let boxSizingCSS = 'box-sizing: border-box;';

	let defs = [
		['panel', Panel, `${boxSizingCSS} display: block; margin: 0; padding: 0;`],
		['splitter', Splitter, `${boxSizingCSS} flex: 0 0 4px; background: #ccc; user-select: none; touch-action: none;`],
		['vlayout', VLayout, `${boxSizingCSS} display: flex; flex-direction: column; align-items: stretch; margin: 0; padding: 0; width: 100%; height: 100%;`],
		['hlayout', HLayout, `${boxSizingCSS} display: flex; flex-direction: row; align-items: stretch; margin: 0; padding: 0; width: 100%; height: 100%;`],
		['deck', Deck, `${boxSizingCSS} display: block; position: relative; margin: 0; padding: 0; width: 100%; height: 100%; overflow: hidden;`],
	];

	let cssText = '*[hidden] { display: none !important; }\n';

	for (let [name, Cls, css] of defs) {
		let tagName = ns.lookupTagName(name);
		customElements.define(tagName, Cls);
		cssText += `${tagName} { ${css} }\n`;
	}

	// Deck children fill the deck
	let deckTag = ns.lookupTagName('deck');
	cssText += `${deckTag} > * { width: 100%; height: 100%; }\n`;

	// Splitter cursor based on parent direction
	let splitterTag = ns.lookupTagName('splitter');
	cssText += `${splitterTag}:hover { background: #999; }\n`;
	cssText += `${ns.lookupTagName('hlayout')} > ${splitterTag} { cursor: col-resize; }\n`;
	cssText += `${ns.lookupTagName('vlayout')} > ${splitterTag} { cursor: row-resize; }\n`;

	// Body reset
	cssText += `${ns.lookupTagName('body')} { ${boxSizingCSS} display: block; width: auto; height: auto; margin: 0; }\n`;

	let style = document.createElement('style');
	style.textContent = cssText;
	document.head.append(style);
}

let layoutElements = {
	register: registerLayoutElements
};

export {
	HBase,
	Panel,
	HLayout,
	VLayout,
	Splitter,
	Deck
}

export default layoutElements;
